import React, { useEffect, useState } from 'react';
import AddRiskForm from './AddRiskForm';

function App() {
  const [risks, setRisks] = useState([]);

  // Load risks from backend
  useEffect(() => {
    fetch('http://localhost:5000/api/risks')
      .then(res => res.json())
      .then(data => setRisks(data));
  }, []);

  // Update state when new risk is added
  const handleRiskAdded = (newRisk) => {
    setRisks([...risks, newRisk]);
  };

  // DELETE handler
  const handleDelete = async (id) => {
    await fetch(`http://localhost:5000/api/risks/${id}`, { method: 'DELETE' });
    setRisks(risks.filter(r => r.id !== id));
  };

  // EDIT handler (example: mark as Resolved)
  const handleEdit = async (risk) => {
    const updated = { ...risk, status: 'Resolved' };
    const response = await fetch(`http://localhost:5000/api/risks/${risk.id}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(updated)
    });
    const newRisk = await response.json();
    setRisks(risks.map(r => r.id === risk.id ? newRisk : r));
  };

  return (
    <div>
      <h1>Risk Dashboard</h1>
      <AddRiskForm onRiskAdded={handleRiskAdded} />

      <table border="1" style={{ marginTop: '20px', width: '100%' }}>
        <thead>
          <tr>
            <th>ID</th>
            <th>Category</th>
            <th>Description</th>
            <th>Score</th>
            <th>Status</th>
            <th>Date Reported</th>
            <th>Actions</th> {/* new column */}
          </tr>
        </thead>
        <tbody>
          {risks.map(risk => (
            <tr key={risk.id}>
              <td>{risk.id}</td>
              <td>{risk.category}</td>
              <td>{risk.description}</td>
              <td>{risk.score}</td>
              <td>{risk.status}</td>
              <td>{new Date(risk.date_reported).toLocaleDateString()}</td>
              <td>
                <button onClick={() => handleEdit(risk)}>Edit</button>
                <button onClick={() => handleDelete(risk.id)}>Delete</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export default App;
